from boltons.cacheutils import LRU, LRI

def check(c, tag):
    # compare dict storage against the linked list
    ll = [(k, v) for (k, v) in c._get_flattened_ll()[1:-1]]  # skip anchors
    ll = [x for x in ll if x[0] is not None and str(x[0]) != '_MISSING']
    d = dict(c)
    llk = dict((k, v) for k, v in ll if not (hasattr(k, 'var_name')))
    if set(llk) != set(d):
        raise AssertionError('%s: key mismatch ll=%r dict=%r' % (tag, set(llk), set(d)))
    for k in d:
        if llk[k] != d[k]:
            raise AssertionError('%s: value mismatch k=%r ll=%r dict=%r' % (tag, k, llk[k], d[k]))

# basic ops coverage
ops = ['set', 'get', 'del', 'pop', 'popitem', 'clear', 'update', 'setdefault', 'copy']
def run(cls, seq):
    c = cls(max_size=3)
    for i, op in enumerate(seq):
        try:
            if op == 'set': c['k%d' % (i % 4)] = i
            elif op == 'get': c.get('k%d' % (i % 4))
            elif op == 'del':
                try: del c['k%d' % (i % 4)]
                except KeyError: pass
            elif op == 'pop': c.pop('k%d' % (i % 4), None)
            elif op == 'popitem':
                try: c.popitem()
                except KeyError: pass
            elif op == 'clear': c.clear()
            elif op == 'update': c.update({'k0': i, 'k1': i+1})
            elif op == 'setdefault': c.setdefault('k%d' % (i % 4), i)
            elif op == 'copy': c.copy()
        except Exception as e:
            return '%s op=%s i=%d: %r' % (cls.__name__, op, i, e)
        try:
            check(c, '%s after %s i=%d' % (cls.__name__, op, i))
        except AssertionError as e:
            return str(e)
    return None

