def make_model(cls, max_size):
    # OrderedDict proxies the linked list: front = least recent, end = most recent
    return OrderedDict()

def check(c, model, ctx):
    # keys+values must match the ll exactly
    if dict(c) != dict(model):
        print('DICT mismatch', ctx, dict(c), dict(model)); return False
    if set(c.keys()) != set(model.keys()):
        print('KEYSET mismatch', ctx, set(c.keys()), set(model.keys())); return False
    if len(c) != len(model) or len(c) > c.max_size:
        print('LEN mismatch', ctx, len(c), len(model), c.max_size); return False
    for k in c:
        if c[k] != model[k]:
            print('GETITEM mismatch', ctx, k, c[k], model[k]); return False
    return True

for cls in (LRU, LRI):
    for trial in range(300):
        max_size = random.randint(1, 5)
        c = cls(max_size=max_size)
        m = OrderedDict()
        for step in range(400):
            k = random.choice('abcdef')
            op = random.choice(['set','get','get','del','pop','setdefault','update','clear','copy','popitem'])
            ctx = (cls.__name__, trial, step, op, k)
