                v = random.randint(0, 99)
                c[k] = v
                if k in m: m.move_to_end(k)
                else:
                    if len(m) >= max_size: m.popitem(last=False)
                    m[k] = v
                if k in m: m[k] = v
            elif op == 'get':
                try: cv = c[k]
                except KeyError:
                    if k in m: print('miss on present key', ctx); raise SystemExit
                    cv = None
                else:
                    if k not in m: print('hit on absent key', ctx); raise SystemExit
                    if cv != m[k]: print('GET mismatch', ctx, cv, m[k]); raise SystemExit
                    if cls is LRU: m.move_to_end(k)
            elif op == 'del':
                if k in m:
                    del c[k]; del m[k]
                elif k in c:
                    print('ghost in dict', ctx); raise SystemExit
            elif op == 'pop':
                if k in m:
                    got, exp = c.pop(k, None), m.pop(k)
                    if got != exp: print('POP mismatch', ctx, got, exp); raise SystemExit
                else:
                    if c.pop(k, '<none>') != '<none>': print('POP ghost', ctx); raise SystemExit
            elif op == 'setdefault':
                d = random.randint(0, 99)
                got = c.setdefault(k, d)
                if k in m:
                    if got != m[k]: print('setdefault hit mismatch', ctx, got, m[k]); raise SystemExit
                    if cls is LRU: m.move_to_end(k)
                else:
                    if len(m) >= max_size: m.popitem(last=False)
                    m[k] = d
                    if got != d: print('setdefault miss mismatch', ctx, got, d); raise SystemExit
            elif op == 'update':
                d = {random.choice('abcdef'): random.randint(0, 99) for _ in range(3)}
