                if kk in m: m.move_to_end(kk)
                else:
                    if len(m) >= max_size: m.popitem(last=False)
                m[kk] = vv
        elif op == 'popitem':
            try: item = c.popitem()
            except KeyError:
                m.clear()
            else:
                if item[0] not in m: print('popitem ghost', ctx, item); raise SystemExit
                m.pop(item[0])
        elif op == 'clear':
            c.clear(); m.clear()
        # compare ORDER: ll order should equal model order (front=oldest)
        ll = [kv[0] for kv in c._get_flattened_ll()][1:-1]  # drop anchors
