import humanize
from math import log
from humanize.filesize import suffixes

def pre_fix(value, binary=False, gnu=False, format="%.1f"):
    suffix = suffixes["gnu"] if gnu else (suffixes["binary"] if binary else suffixes["decimal"])
    base = 1024 if (gnu or binary) else 1000
    bytes_ = float(value); abs_bytes = abs(bytes_)
    if abs_bytes == 1 and not gnu: return "%d Byte" % int(bytes_)
    if abs_bytes < base: return ("%dB" % int(bytes_)) if gnu else ("%d Bytes" % int(bytes_))
    exp = int(min(log(abs_bytes, base), len(suffix)))
    return format % (bytes_ / (base**exp)) + ("" if gnu else " ") + suffix[exp-1]

for v, kw in [(1234567, dict(format="%.1f%%")),
              (1234567, dict(format="%.1f B")),
              (10**9, dict(format="%a")),
              (10**30, dict(format="%.1f%%")),   # largest unit: guard makes the parse unnecessary
             ]:
    try: new = humanize.naturalsize(v, **kw)
    except Exception as e: new = f"{type(e).__name__}: {e}"
    try: old = pre_fix(v, **kw)
    except Exception as e: old = f"{type(e).__name__}: {e}"
    print(f"naturalsize({v}, {kw})\n    pre-fix: {old!r}\n    post-fix: {new!r}")
