const B = require(require('path').resolve('work/repo'))
const H = require(require('path').resolve('work/hard'))
const optsList = [{}, { includePrerelease: true }, { rtl: true }, { rtl: true, includePrerelease: true }, { loose: true, includePrerelease: true }, { rtl: true, loose: true }]
const d = (v) => v ? v.version + '|' + JSON.stringify(v.prerelease) + '|' + JSON.stringify(v.build) : 'null'
let seed = 7
const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648
const parts = ['1','2','10','0','01','17','00','rc','alpha','beta','nightly','a','f3','7f3c','9e1d','4821','2024','01','15','.','-','+',' ','/','v','=','x','X','build','meta','a-b','1a','2b','0x','_','*','^']
const p = () => parts[Math.floor(rnd() * parts.length)]
const gen = () => { let s = ''; const n = 1 + Math.floor(rnd() * 10); for (let i=0;i<n;i++) s += p(); return s }
const c = { A:0, B:0, H:0, aNullHardVal: [], aValHardNull: [], aValFixNull: [], aNullFixVal: [] }
const N = 60000
for (let i = 0; i < N; i++) {
  const v = gen()
  for (const o of optsList) {
    const a = A.coerce(v, o), b = B.coerce(v, o), h = H.coerce(v, o)
    const da = d(a), db = d(b), dh = d(h)
    if (da !== dh) {
      if (a === null) c.aNullHardVal.push([v, JSON.stringify(o), dh])
      else if (h === null) c.aValHardNull.push([v, JSON.stringify(o), da])
    }
    if (da !== db) {
      if (a === null) c.aNullFixVal.push([v, JSON.stringify(o), db])
      else if (b === null) c.aValFixNull.push([v, JSON.stringify(o), da])
    }
  }
}
console.log('inputs', N, 'opts', optsList.length)
console.log('old-null -> hardened-value:', c.aNullHardVal.length)
console.log('old-value -> hardened-null:', c.aValHardNull.length)
console.log('old-null -> fixed-value:', c.aNullFixVal.length)
console.log('old-value -> fixed-null:', c.aValFixNull.length)
console.log('--- old-value -> fixed-null (regressions of the plain fix)')
c.aValFixNull.slice(0, 12).forEach(x => console.log('  ', JSON.stringify(x)))
console.log('--- old-null -> hardened-value')
c.aNullHardVal.slice(0, 12).forEach(x => console.log('  ', JSON.stringify(x)))
console.log('--- old-value -> hardened-null')
c.aValHardNull.slice(0, 12).forEach(x => console.log('  ', JSON.stringify(x)))
