// Why does greedy prerelease + (?:\$|[^\d]) truncate at a digit+letter boundary?
// Build minimal repro:
const PID='(?:0|[1-9]\\\\d*|\\\\d*[a-zA-Z-][a-zA-Z0-9-]*)'
